class Spell {
  constructor(name) {
    this.name = name;
  }

  cast() {
    return `${this.name} is cast with a gentle hum.`;
  }
}

class FireballSpell extends Spell {
  constructor(name, damage) {
    super(name);
    this.damage = damage;
  }

  cast() {
    return `${this.name} explodes for ${this.damage} damage!`;
  }
}

class HealSpell extends Spell {
  constructor(name, healingAmount) {
    super(name);
    this.healingAmount = healingAmount;
  }

  cast() {
    return `${this.name} restores ${this.healingAmount} health!`;
  }
}

// Test cases (do not modify)
const fireball = new FireballSpell("Inferno Blast", 40);
const heal = new HealSpell("Greater Restoration", 50);
const basicSpell = new Spell("Minor Charm");

console.log(fireball.cast());
console.log(heal.cast());
console.log(basicSpell.cast());

